function tryMove(m,e,dx,dy){const r=e.r||.3;const bl=(x,y)=>solidAt(m,x-r,y-r)||solidAt(m,x+r,y-r)||solidAt(m,x-r,y+r)||solidAt(m,x+r,y+r)||(e.type==='mob'&&safeAt(m,x,y));let moved=false;if(dx&&!bl(e.x+dx,e.y)){e.x+=dx;moved=true}if(dy&&!bl(e.x,e.y+dy)){e.y+=dy;moved=true}return moved}
