  if(!walkable(m,tx,ty,mob)){let best=null,bd=1e9;for(let r=1;r<=3&&!best;r++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){const x=tx+dx,y=ty+dy;if(walkable(m,x,y,mob)){const d=Math.hypot(dx,dy);if(d<bd){bd=d;best=[x,y]}}}if(!best)return[];tx=best[0];ty=best[1]}
