function updTeles(dt){for(let i=teles.length-1;i>=0;i--){const t=teles[i];t.t+=dt;if(t.t>=t.dur){teles.splice(i,1);if(t.fire)t.fire()}}}
// ---------- NPCs, villagers, bots ----------
function spawnNpcs(){for(const id in MAPS){const m=MAPS[id];for(const d of m.npcDefs||[])npcs.push(Object.assign({type:'npc',m:id,r:.3,d8:0,anim:'idle',frame:0,animT:0,bub:null,ambT:rnd(8,25),hx:d.x,hy:d.y,ri:0,path:[],rp:0},d,{look:Object.assign({},d.look)}))}}
function updNpc(n,dt){if(n.bub&&(n.bub.t-=dt)<=0)n.bub=null;n.moving=false;
  if(n.role==='villager'){const night=isNight();const target=night?MAPS.world.homes[n.home]:n.route[n.ri];if(!n.wait||n.wait<=0){const dd=Math.hypot(n.x-target[0],n.y-target[1]);if(dd>.3){steer(n,target[0],target[1],1.6,dt,false)}else if(night){n.indoor=1}else{n.wait=rnd(2,6);n.ri=(n.ri+1)%n.route.length}}else n.wait-=dt;if(!night)n.indoor=0}
  if(n.moving){n.anim='walk';n.animT+=dt*.4;n.frame=Math.floor(n.animT*10)%8}else{n.anim='idle';n.frame=Math.floor(T*1.4+n.hx)%2;if(n.role!=='villager'&&P&&P.map===n.m&&dist(n,P)<4)n.d8=dir8(scrAng(P.x-n.x,P.y-n.y))}
  n.ambT-=dt;if(n.ambT<=0){n.ambT=rnd(16,34);if(P&&P.map===n.m&&dist(n,P)<9&&!n.hidden&&!n.indoor){const L=NPC_AMB[n.role];if(L)say(n,pick(L),4)}}}
const NPC_AMB={bank:['Seu ouro está seguro comigo.','Cuidado lá fora. O banco não guarda vidas.'],temple:['Que a luz te guie.','Feridos, venham ao templo.'],shop:['Poções fresquinhas!','Pergaminho de Retorno, nunca saia sem um.'],smith:['Aço bom não se faz com pressa.','*clang* *clang*'],hunter:['O bosque está estranho ultimamente.','Já viu um lobo do tamanho de um cavalo?','As flores que brilham crescem perto das pedras velhas. Minha avó dizia que eram lanternas pros mortos.'],guard:['Estrada leste aberta.','À noite os lobos ficam ousados.'],villager:['Bom dia!','Viu meu gato por aí?','Dizem que o cemitério é assombrado...','O pão da taverna é o melhor da região.'],tome:['Obrigado por me salvar!']};
function spawnBots(){const W=MAPS.world;const zones=[[14,2,42,11],[32,26,43,60],[49,24,62,60],[4,34,29,60],[33,30,42,58],[14,14,28,28]];BOT_NAMES.forEach(([name,cls],i)=>{const z=zones[i];let x,y;for(let k=0;k<60;k++){x=rint(z[0],z[2]);y=rint(z[1],z[3]);if(walkable(W,x,y))break}
  const gear=START[cls];const fake={eq:{},skin:i%4,hairC:(i*3)%5,hs:i%3?'short':'long',capeC:(i*2)%5,beard:i===3};for(const [sl,id] of Object.entries(gear))fake.eq[sl]={id};if(i===2)fake.eq.peito={id:'cota'};if(i===4)fake.eq.cabeca={id:'elmo'};
  bots.push({type:'bot',name,cls,m:'world',look:playerLook(fake),x:x+.5,y:y+.5,r:.3,zone:z,d8:0,anim:'idle',frame:0,animT:0,atkT:0,atkCD:0,target:null,path:[],rp:0,wT:0,lv:[8,6,12,4,9,3][i],town:i===5})})}
function updBot(b,dt){b.atkCD-=dt;b.atkT-=dt;if(b.bub&&(b.bub.t-=dt)<=0)b.bub=null;b.moving=false;const W=MAPS.world;
  if(b.target&&(b.target.dying||b.target.dead))b.target=null;
  if(!b.target){b.wT-=dt;if(b.wT<=0){b.wT=rnd(1.5,4);let best=null,bd=9;if(!b.town)for(const m of mobs){if(m.m!=='world'||m.dying||m.def.boss||m.def.elite||m.def.ai==='dummy'||m.target===P)continue;if(m.x<b.zone[0]||m.x>b.zone[2]+1||m.y<b.zone[1]||m.y>b.zone[3]+1)continue;const d=dist(b,m);if(d<bd){bd=d;best=m}}
      if(best&&Math.random()<.6)b.target=best;else{b.gx=rint(b.zone[0],b.zone[2])+.5;b.gy=rint(b.zone[1],b.zone[3])+.5;if(!walkable(W,Math.floor(b.gx),Math.floor(b.gy)))b.gx=null}}
    if(b.gx!=null){steer(b,b.gx,b.gy,2.8,dt,false);if(Math.hypot(b.x-b.gx,b.y-b.gy)<.4)b.gx=null}}
  else{const t=b.target,dd=dist(b,t),range=b.cls==='g'||b.cls==='l'?1.4:5;if(dd<=range&&los(W,b,t)){b.d8=dir8(scrAng(t.x-b.x,t.y-b.y));if(b.atkCD<=0){b.atkCD=rnd(.9,1.3);b.atkT=.3;b.atkAnim=b.cls==='g'||b.cls==='l'?'atk':b.cls==='a'?'bow':'cast';const a=Math.atan2(t.y-b.y,t.x-b.x);if(b.cls==='g'||b.cls==='l'){if(t.m===M.id)fx.push({type:'slash',x:b.x,y:b.y,a,r:1.4,t:0,life:.16,arc:1.8,dim:1});later(.08,()=>botHit(t,b,1))}else{const sm=M;M=W;shoot('b',b.x,b.y,a,b.cls==='a'?14:10,b.cls==='a'?'arrow':'bolt',1,{},b);M=sm;projs[projs.length-1].m='world'}}}else steer(b,t.x,t.y,2.8,dt,false)}
  if(b.atkT>0){b.anim=b.atkAnim;b.frame=clamp(Math.floor((1-b.atkT/.3)*4),0,3)}else if(b.moving){b.anim='walk';b.animT+=dt*.7;b.frame=Math.floor(b.animT*10)%8}else{b.anim='idle';b.frame=Math.floor(T*1.5)%2}}
function botSay(b,txt){if(!b)return;say(b,txt,4.5);log(`${b.name}: ${txt}`,'bot')}
// ---------- interactions & dialogs ----------
function openBossChest(e){e.opened=true;e.obj.cv=ART.chestOpen.cv;sfx('chest');burstAt(e.x,e.y,0xffd23a,30,80);const g=rint(160,360);loots.push({gold:g,x:e.x+.4,y:e.y+.4,m:M.id,t:120,age:0});
  const lvCap=Math.max(6,P.lv+3),pool=DROP_POOL.filter(id=>BASES[id].lv<=lvCap),mine=pool.filter(id=>!BASES[id].cls||BASES[id].cls===P.cls);
  for(let i=0;i<2;i++){const id=pick(Math.random()<.75&&mine.length?mine:pool);loots.push({item:makeItem(id,Math.max(1,rollRar(2.5))),x:e.x+rnd(-.6,.8),y:e.y+rnd(-.6,.6),m:M.id,t:180,age:0})}
  const bd=M.boss&&MOBS[M.boss[0]];if(bd&&Math.random()<.35){const eqs=bd.drops.filter(([id])=>BASES[id]&&BASES[id].t==='eq');if(eqs.length){const [id]=pick(eqs);loots.push({item:makeItem(id,2),x:e.x+.2,y:e.y-.4,m:M.id,t:180,age:0})}}
  loots.push({item:makeItem('pot_hp2',0),x:e.x-.4,y:e.y+.2,m:M.id,t:120,age:0});log('O baú do chefe se abre: ouro, equipamento e poções!','loot','#ffa53a');toast('Baú do chefe','Recompensa pela vitória')}
function interactables(){const out=[];for(const n of npcs)if(n.m===M.id&&!n.hidden&&!n.indoor)out.push({kind:'npc',e:n,x:n.x,y:n.y,label:'Falar com '+n.n.split(',')[0]});for(const a of M.acts){const label=a.label||{sealed:'Examinar porta selada',grave:'Examinar lápide',cave:'Entrar na Toca dos Goblins',exit:'Sair',chest:'Abrir baú'}[a.kind];if(a.kind==='chest'&&P.flags.chests[a.id])continue;if(a.needQ&&!(P.q[a.needQ]>=1))continue;if(a.kind==='bchest'&&(!M.bossDown||a.opened))continue;if(a.kind==='mine'&&a.t>0)continue;out.push({kind:a.kind,e:a,x:a.x,y:a.y,label})}return out}
function nearestInteract(){let best=null,bd=1.9;for(const it of interactables()){const d=Math.hypot(it.x-P.x,it.y-P.y);if(d<bd){bd=d;best=it}}return best}
function interact(it){if(!it||P.dead)return;const e=it.e;
  if(it.kind==='npc'){talk(e);return}
  if(it.kind==='mine'){mineNode(e);return}
  if(it.kind==='bchest'){openBossChest(e);return}
  if(it.kind==='cave'){changeMap('dungeon',MAPS.dungeon.spawnPt[0],MAPS.dungeon.spawnPt[1]);return}
  if(it.kind==='exit'){const to=e.to||'world',at=e.at||MAPS.world.caveOut;changeMap(to,at[0],at[1]);return}
  if(it.kind==='enter'){const at=e.at||MAPS[e.to].spawnPt;if(e.warp){burstAt(P.x,P.y,0x9ad8ff,26,70);sfx('blink');P.warpCD=1.4}changeMap(e.to,at[0],at[1]);if(e.msg)log(e.msg,'sys');return}
  if(it.kind==='chest'){P.flags.chests[e.id]=1;e.obj.cv=ART.chestOpen.cv;const g=rint(60,140);loots.push({gold:g,x:e.x+.4,y:e.y+.4,m:M.id,t:90,age:0});const pool=DROP_POOL.filter(id=>BASES[id].lv<=Math.max(5,P.lv+1));const id=pick(pool.filter(i=>!BASES[i].cls||BASES[i].cls===P.cls));loots.push({item:makeItem(id,Math.max(1,rollRar(1))),x:e.x+.6,y:e.y-.2,m:M.id,t:120,age:0});sfx('chest');log('Você encontrou um baú escondido!','sys');if(e.id==='bosque'&&!countItem('pagina')&&!P.flags.santuario){addItem(makeItem('pagina'));P.q.santuario=Math.max(P.q.santuario||0,1);log('Dentro do baú há uma página rasgada de diário. (Veja no inventário.)','sys');later(.6,()=>dlg('Página Rasgada',BASES.pagina.d,[{l:'Guardar'}]))}if(e.id==='santuario')P.q.santuario=Math.max(P.q.santuario||0,2);gainExp(40,1);save();return}
  if(it.kind==='sealed'){if(P.flags.sealed){dlg('Porta selada','A sala atrás da porta está vazia agora. Só restou o cheiro de incenso velho.',[]);return}
    if(!countItem('chave_osso')){dlg('Porta selada','Uma porta de ferro sob o templo, com um crânio entalhado no lugar da fechadura. Ninguém na vila admite saber o que tem do outro lado.',[]);if(!P.q.porta){P.q.porta=1;log('Descoberta: A Porta Selada.','sys');uiDirty=1}return}
    takeItem('chave_osso',1);P.flags.sealed=1;P.q.porta=2;sfx('chest');const pool=DROP_POOL.filter(id=>BASES[id].lv<=P.lv+2&&(!BASES[id].cls||BASES[id].cls===P.cls));loots.push({item:makeItem(pick(pool),3),x:e.x+.6,y:e.y+.6,m:M.id,t:300,age:0});loots.push({gold:400,x:e.x+.3,y:e.y+.9,m:M.id,t:300,age:0});gainExp(500,1);
    dlg('Porta selada','A Chave de Osso gira sozinha. Lá dentro, um relicário do Abade: ouro, um equipamento antigo e um diário. A última página diz: "o Rei Goblin me prometeu os ossos de Pedravale". Então os dois estavam juntos...',[{l:'Guardar tudo',pri:1}]);save();return}
  if(it.kind==='grave'){if(P.q.tumulo>=3){dlg('Lápide sem nome','A terra está calma agora. Alguém deixou flores frescas sobre a pedra.',[]);return}
    if(isNight()){if(mobs.some(m=>m.kind==='guardiao'&&!m.dying)){return}P.q.tumulo=2;dlg('Lápide sem nome','Um frio sobe pela sua espinha. Uma voz rouca sussurra: "Lembre-se de mim..." A terra se abre.',[{l:'Preparar-se',pri:1}]);const g=spawnMob('guardiao',M,null,[e.x+1.2,e.y+.4]);g.target=P;sfx('roar');log('Descoberta: O Túmulo Sem Nome.','sys')}
    else{if(!P.q.tumulo){P.q.tumulo=1;log('Descoberta: O Túmulo Sem Nome.','sys');uiDirty=1}dlg('Lápide sem nome','A pedra não tem nome, só uma frase meio apagada: "...vigia até que o lembrem". A terra em volta parece mexida. Talvez algo aconteça quando a vila dormir.',[])}}}
function talk(n){const nm=n.n;if(n.role!=='villager')n.d8=dir8(scrAng(P.x-n.x,P.y-n.y));
  switch(n.role){
    case'bank':dlg(nm,'Bem-vindo ao Banco de Pedravale. O que você guardar aqui fica seguro, mesmo que você caia lá fora.',[{l:'Abrir cofre',pri:1,f:openBank},{l:'Algum boato?',f:()=>dlg(nm,'Ninguém sabe quem está na lápide sem nome do cemitério. Os coveiros juram que, à noite, a terra se mexe sozinha. Eu não pergunto, só guardo ouro.',[])},{l:'Até logo'}]);break;
    case'temple':{const d=D();P.hp=d.maxHp;P.mp=d.maxMp;burstAt(P.x,P.y,0xfff0b0,20,40);sfx('heal');dlg(nm,'Que a luz te restaure. Se você cair lá fora, despertará aqui, no templo. Também preparo poções e elixires, se você trouxer os ingredientes.',[{l:'Alquimia',pri:1,f:()=>alchemyMenu(nm)},{l:'Obrigado'}]);break}
    case'refine':refineMenu(nm);break;
    case'evo':evoMenu(nm);break;
    case'pets':petMenu(nm);break;
    case'shop':openShop('lia',nm);break;
    case'rshop':openShop(n.shop,nm);break;
    case'quest':rqTalk(n);break;
    case'talker':dlg(nm,pick(n.lines||['...']),[{l:'Até mais'}]);break;
    case'travel':{const here=CITIES.find(c=>c.map===n.m);dlg(nm,`Posso abrir um portal para qualquer cidade. A passagem custa ${TRAVEL_COST} ouro. Para onde?`,[...CITIES.filter(c=>c!==here).map(c=>({l:`${c.n} — ${MAPS[c.map].name} (Nv ${({world:'1–11',gelo:'13–24',japao:'23–34',deserto:'33–44',selva:'41–52'})[c.map]||'?'})`,pri:0,f:()=>travelTo(c)})),{l:'Agora não'}]);break}
    case'smith':{const q=P.q.filho;const opts=[{l:'Ver mercadorias',pri:1,f:()=>openShop(P.q.filho>=3?'brunoMestre':'bruno',nm)},{l:'Refinar equipamento',f:()=>refineMenu(nm)}];
      if(q===0)dlg(nm,'Meu filho Tomé foi buscar lenha no bosque há três dias e não voltou. Os guardas dizem que viram goblins perto do rio... Se você for para aqueles lados, procure por ele. Por favor.',[{l:'Vou procurar',pri:1,f:()=>{P.q.filho=1;log('Missão: O Filho do Ferreiro','sys');sfx('ok');uiDirty=1}},...opts,{l:'Agora não'}]);
      else if(q===1)dlg(nm,'Nenhuma notícia do Tomé ainda? Dizem que os goblins levam prisioneiros para a toca deles, depois do rio.',[...opts,{l:'Continuo procurando'}]);
      else if(q===2){P.q.filho=3;const it=makeItem('martelo');if(!addItem(it))loots.push({item:it,x:P.x,y:P.y,m:M.id,t:300,age:0});gainExp(350,1);P.gold+=150;sfx('lvl');log('Recompensa: Martelo do Aprendiz, 150 ouro. Bruno agora vende o estoque do mestre.','loot','#ffa53a');uiDirty=1;
        dlg(nm,'Tomé chegou em casa! Eu nem sei como agradecer. Fique com isto: o primeiro martelo que ele forjou. E daqui pra frente, minha forja inteira está aberta pra você, inclusive o estoque do mestre.',[...opts,{l:'Obrigado'}])}
      else dlg(nm,'O Tomé já voltou a martelar. Vai ser um ferreiro melhor que o pai.',[...opts,{l:'Até mais'}]);break}
    case'hunter':{const q=P.q.cacada;if(q===0)dlg(nm,'Trinta invernos caçando nesse bosque, e um lobo eu nunca peguei: um alfa enorme, com uma cicatriz no flanco. Ele quase nunca aparece, e quando aparece, a matilha fica mais ousada. Traga a pele dele e eu te dou algo que vale a caçada.',[{l:'Aceito',pri:1,f:()=>{P.q.cacada=1;log('Missão: A Última Caçada','sys');sfx('ok');uiDirty=1}},{l:'Talvez depois'}]);
      else if(q===1){if(countItem('pele_alfa')){takeItem('pele_alfa',1);P.q.cacada=2;const id=P.cls==='a'?'arco_cacador':'amuleto_cacador';const it=makeItem(id);if(!addItem(it))loots.push({item:it,x:P.x,y:P.y,m:M.id,t:300,age:0});gainExp(400,1);sfx('lvl');log(`Recompensa: ${BASES[id].n}.`,'loot','#ffa53a');uiDirty=1;dlg(nm,'É ele. Essa cicatriz fui eu que fiz, muitos anos atrás. A caçada terminou... Fique com isto. Você merece mais do que eu.',[{l:'Obrigado'}])}else dlg(nm,'O alfa anda pelo Bosque de Vellmor, a leste do rio... ou a oeste, depende do humor dele. Ouça os uivos.',[{l:'Certo'}])}
      else dlg(nm,'O bosque parece mais calmo sem o velho alfa. Estranho sentir falta de um inimigo.',[{l:'Até mais'}]);break}
    case'guard':{const tips=['As Terras Goblins ficam depois do rio. Você pode entrar. Mas talvez não consiga voltar.','Javalis avisam antes de investir: eles param e bufam. Saia da linha e deixe que batam na pedra.','O goblin de escudo defende tudo pela frente. Vá pelos lados ou use algo que quebre a guarda.','Arqueiros goblins miram antes de soltar a flecha. Dash na hora certa e a flecha passa.','À noite, as feras enxergam melhor que você. E dizem que o cemitério não dorme.','O banco do Osvaldo guarda o que você não quer perder.','A porta do mausoléu no cemitério não está trancada. Ninguém que desceu voltou falando muito.','No fim da estrada leste fica o Forte Goblin. O Rei deles nunca sai de lá.'];n.tip=(n.tip||0)+1;dlg(nm,tips[(n.tip-1)%tips.length],[{l:'Entendido'}]);break}
    case'tome_cage':{if(P.q.filho>=2){dlg(nm,'Vou correndo pra casa!',[]);break}P.q.filho=2;n.hidden=1;npcs.find(x=>x.id==='tome').hidden=0;burstAt(n.x,n.y,0xfff0b0,16,40);sfx('ok');uiDirty=1;dlg(nm,'Você veio! O Chefe Goblin me pegou no bosque e queria que eu consertasse as armas deles. Vou fugir pela saída enquanto eles estão distraídos. Diga ao meu pai que estou indo pra casa!',[{l:'Vá, rápido!',pri:1}]);break}
    case'tome':dlg(nm,'Obrigado por me tirar daquela jaula! Meu pai tem uma coisa pra você.',[{l:'De nada'}]);break;
    default:dlg(nm,pick(['Bom dia, aventureiro!','Dizem que os goblins estão mais ousados este ano.','Já provou o pão da taverna?','Meu avô dizia que o rio tinha peixes de ouro.']),[{l:'Até mais'}])}}
// ---------- world flow ----------
function unstick(m,e){if(!blockedAt(m,e.x,e.y,e.r||.3))return;for(let r=.5;r<6;r+=.5)for(let a=0;a<6.28;a+=.4){const x=e.x+Math.cos(a)*r,y=e.y+Math.sin(a)*r;if(!blockedAt(m,x,y,e.r||.3)){e.x=x;e.y=y;return}}}
function blockedAt(m,x,y,r){return solidAt(m,x-r,y-r)||solidAt(m,x+r,y-r)||solidAt(m,x-r,y+r)||solidAt(m,x+r,y+r)}
function changeMap(id,x,y){if(bossActive&&bossActive.m===M.id&&id!==M.id)resetBoss();P.map=id;M=MAPS[id];P.x=x;P.y=y;unstick(M,P);P.kx=P.ky=0;P.vx=P.vy=0;P.stun=0;P.dash=null;projs.length=0;teles.length=0;cam.init=false;lastRegion=null;sfx('door');P.fish=null;if(pet){pet.x=P.x;pet.y=P.y}onMapStats(id);save()}
let lastRegion=null,lvlFx=0;
function regionAt(m,x,y){for(const r of m.regions)if(x>=r.r[0]&&x<=r.r[2]+1&&y>=r.r[1]&&y<=r.r[3]+1)return r;return m.regions[m.regions.length-1]}
function closeCircle(){const w=MAPS.world,c=w.circle;if(!c||!c.open)return;c.open=false;w.objs=w.objs.filter(o=>!o.portal||o.keep);w.acts=w.acts.filter(a=>!(a.kind==='enter'&&a.to==='santuario'));for(const o of c.plants)o.plant.t=0;if(P)P.flags.santuario=0;log('O portal do círculo de pedras se fechou. As plantas apagaram.','sys')}
function openCircle(quiet){const w=MAPS.world,c=w.circle;if(!c||c.open)return;c.open=true;const o=prop(w,38,36,ART.portalBase,{block:null,noShadow:1,portal:1,light:{dx:0,dy:-28,r:115,cold:1}});o.k=74.2;w.acts.push({kind:'enter',to:'santuario',x:38.6,y:37,label:'Atravessar o portal',msg:'O portal puxa você como água fria. Do outro lado, musgo e silêncio.'});w.chunks.clear();if(!quiet){shake=.4;sfx('victory');log('As pedras vibram e um portal se abre no centro do círculo. Ele não vai durar para sempre: se você cair, ele se fecha.','sys');toast('Um portal se abriu','Se você morrer, o portal se fecha')}P.flags.santuario=1;if(P.q.santuario<2)P.q.santuario=2;uiDirty=1;save()}
function updWorld(dt){TIME=(TIME+dt/CFG.dayLength)%1;for(const o of M.plants)if(o.plant.t>0)o.plant.t-=dt;
  {const c=MAPS.world.circle;if(c&&!c.open&&M.id==='world'&&c.plants.every(o=>o.plant.t>0)){if(isNight())openCircle();else if(!c.hinted||T-c.hinted>20){c.hinted=T;toast('As pedras esperam','Nada acontece... talvez sob a lua');log('As flores-lume brilham juntas, mas as pedras continuam frias. Talvez precise ser à noite.','npc')}}}
  weather.t-=dt;if(weather.t<=0){weather.t=rnd(120,260);weather.target=weather.target>0?(Math.random()<.35?rnd(.4,1):0):(Math.random()<.6?rnd(.5,1):0);if(weather.target>0)log('Nuvens pesadas cobrem o céu.','sys')}weather.rain+=(weather.target-weather.rain)*Math.min(1,dt*.3);
  for(let i=timers.length-1;i>=0;i--){timers[i].t-=dt;if(timers[i].t<=0){const f=timers[i].fn;timers.splice(i,1);f()}}
  for(let i=respawnQ.length-1;i>=0;i--){const r=respawnQ[i];r.t-=dt;if(r.t<=0){respawnQ.splice(i,1);spawnMob(r.kind,MAPS[r.m],r.rect,r.at)}}
  for(let i=loots.length-1;i>=0;i--){loots[i].age+=dt;if((loots[i].t-=dt)<=0)loots.splice(i,1)}
  alphaT-=dt;if(alphaT<=0){alphaT=rnd(70,130);if(!mobs.some(m=>m.kind==='lobo_alfa'&&!m.dying)&&Math.random()<(isNight()?.7:.35)){spawnMob('lobo_alfa',MAPS.world,[33,30,43,60]);log('Um uivo longo e grave ecoa pelo Bosque de Vellmor...','sys')}}
  chatT-=dt;if(chatT<=0){chatT=rnd(10,24);botSay(pick(bots),pick(BOT_LINES))}
  const r=regionAt(M,P.x,P.y);if(r!==lastRegion){lastRegion=r;regionBanner(r);const key=M.id+r.n;if(!P.flags.seen[key]){P.flags.seen[key]=1;if(r.dg>0){const xp=CFG.discoverXp[r.dg]||10;later(.8,()=>{gainExp(xp,1);log(`Região descoberta: ${r.n} (+${xp} XP)`,'sys')})}}}}
let alphaT=40,chatT=12;
